if mibBuilder.loadTexts: cAdslAtucDmtConfFastFecSize.setReference('ANSI T1.413-1998 Issue 2, Network and Customer Installation\n        Interfaces - Asymmetric Digital Subscriber Line (ADSL)\n        Metallic Interfaces.')
if mibBuilder.loadTexts: cAdslAtucDmtConfFastFecSize.setStatus('current')
if mibBuilder.loadTexts: cAdslAtucDmtConfFastFecSize.setDescription('This object specifies the initial number of FEC redundancy\n        bytes the ATU-C appends to downstream frames transmitted over\n        the fast channel during the training sequence.  The ATU-C can\n        fallback from this value depending on the aggregate data rate\n        achieved during training.\n\n        It is desirable to choose a large FEC size, thereby increasing\n        the chance of being able to correct errors in the data delivered\n        by a frame.  However, additional FEC redundancy bytes increases\n        frame overhead, and thus frame latency.')
cAdslAtucDmtConfInterleaveFecSize = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 130, 1, 14, 1, 4), DmtFecSize().clone(16)).setUnits('bytes').setMaxAccess("readcreate")
if mibBuilder.loadTexts: cAdslAtucDmtConfInterleaveFecSize.setReference('ANSI T1.413-1998 Issue 2, Network and Customer Installation\n        Interfaces - Asymmetric Digital Subscriber Line (ADSL)\n        Metallic Interfaces.')
if mibBuilder.loadTexts: cAdslAtucDmtConfInterleaveFecSize.setStatus('current')
if mibBuilder.loadTexts: cAdslAtucDmtConfInterleaveFecSize.setDescription('This object specifies the initial number of FEC redundancy\n        bytes the ATU-C appends to downstream frames transmitted over\n        the interleaved channel during the training sequence.  The\n        ATU-C can fallback from this value depending on the aggregate\n        data rate achieved during training.\n\n        It is desirable to choose a large FEC size, thereby increasing\n        the chance of being able to correct errors in the data delivered\n        by a frame.  However, additional FEC redundancy bytes increases\n        frame overhead, and thus frame latency.\n\n        The value of this object must be a integral multiple of the\n        value of cAdslAtucDmtConfCodewordSize.')
cAdslAtucDmtConfCodewordSize = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 130, 1, 14, 1, 5), DmtCodewordSize().clone(16)).setUnits('symbols').setMaxAccess("readcreate")
