cAdslAturDmtConfCodewordSize = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 130, 1, 14, 1, 12), DmtCodewordSize().clone(16)).setUnits('symbols').setMaxAccess("readcreate")
